<!DOCTYPE html><html lang="id"><?php include __DIR__.'/../../../../components/dashboard/mitra/Head.php'; ?><body class="bg-slate-50 font-[Poppins] text-gray-900 overflow-x-hidden"><?php include __DIR__.'/../../../../components/dashboard/mitra/Sidebar.php'; ?><?php include __DIR__.'/../../../../components/dashboard/mitra/Header.php'; ?><main class="min-h-screen pt-20 bg-slate-50 lg:ml-64"><div class="px-4 py-6 mx-auto sm:px-6 sm:py-8 lg:px-8 max-w-6xl"><a href="<?=e(url('/dashboard/mitra/logbook'))?>" class="text-sm text-blue-600">← Kembali</a><h1 class="mt-3 text-2xl font-bold text-gray-900">Minggu <?=e($week['minggu_ke'])?> · <?=e($week['mahasiswa_nama'])?></h1><p class="mt-1 text-sm text-gray-500"><?=e($week['nim'])?> · <?=e(date('d M Y',strtotime($week['tanggal_mulai'])))?> – <?=e(date('d M Y',strtotime($week['tanggal_selesai'])))?></p><div class="mt-5 overflow-hidden bg-white border border-gray-100 shadow-sm rounded-2xl"><div class="overflow-x-auto"><table class="w-full min-w-[720px] text-sm"><thead class="bg-gray-50"><tr><th class="px-4 py-3 text-left">Tanggal</th><th class="px-4 py-3 text-left">Masuk</th><th class="px-4 py-3 text-left">Pulang</th><th class="px-4 py-3 text-left">Kegiatan</th></tr></thead><tbody class="divide-y divide-gray-100"><?php foreach($week['daily'] as $day):?><tr><td class="px-4 py-4"><?=e(date('D, d M Y',strtotime($day['tanggal'])))?></td><td class="px-4 py-4"><?=e($day['jam_masuk']?:'-')?></td><td class="px-4 py-4"><?=e($day['jam_pulang']?:'-')?></td><td class="px-4 py-4 whitespace-pre-line"><?=e($day['kegiatan'])?><?php if($day['status_kehadiran']==='tidak_hadir'):?><div class="mt-1 text-xs text-amber-700">Alasan: <?=e($day['alasan_ketidakhadiran'])?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><div class="mt-5 p-4 bg-blue-50 border border-blue-200 rounded-xl text-sm text-blue-800">Status pada dashboard mitra hanya menunjukkan apakah mitra sudah menandatangani atau belum. Status tanda tangan dosen tidak ditampilkan di sisi mitra.</div><div class="mt-5"><?php if(($week['status']??'')==='menunggu_mitra'): $signatureAction=url('/dashboard/mitra/logbook/tanda-tangan/'.(int)$week['id']);$signatureButtonLabel='Tanda Tangani sebagai Mitra';$signatureStageLabel='Tanda Tangan Pembimbing Lapangan / Mitra';include __DIR__.'/../../../../components/dashboard/logbook/SignaturePad.php';else:?><div class="p-5 bg-white border border-gray-100 rounded-2xl"><p class="text-sm font-semibold text-gray-900">Minggu ini sudah ditandatangani mitra.</p><?php if(!empty($signatures['mitra'])):?><img src="<?=e(url('/dashboard/logbook/file/signature/'.(int)$signatures['mitra']['id']))?>" class="object-contain w-full h-24 mt-3 bg-gray-50 rounded-lg" alt="Tanda tangan mitra"><?php endif;?></div><?php endif;?></div></div></main></body></html>
